{
  "$schema": "https://opencode.ai/config.json",
  "$comment": "OpenCode registration for the Production Master thin client. packages/adapter-opencode ships a runnable dist/cli.js. OpenCode spawns it once as a persistent local MCP server and speaks newline-delimited JSON-RPC 2.0 (MCP: initialize, tools/list, tools/call) over its stdio — not the request/response CLI dispatch Claude Code's slash commands use. The `mcp` argument selects that mode; every tools/call is forwarded into the same runtime.update() the CLI's direct `update` subcommand uses, so mutation gating and session scoping are never duplicated. A user still runs `node packages/adapter-opencode/dist/cli.js login` once beforehand — login/investigate/connect stream a run and are not exposed as MCP tools. The thin client authenticates with device-code login and talks to the hosted service over HTTPS + SSE; set PM_SERVICE_URL (default https://api.productionmaster.dev). Secrets are ${ENV} references only, never literals.",
  "mcp": {
    "production-master": {
      "type": "local",
      "command": ["node", "packages/adapter-opencode/dist/cli.js", "mcp"],
      "enabled": true,
      "environment": {
        "PM_SERVICE_URL": "{env:PM_SERVICE_URL}"
      }
    }
  }
}

{
  "name": "@production-master/adapter-claude-code",
  "version": "0.0.0-local",
  "description": "Claude Code thin host adapter over @production-master/plugin-core — renders the statusline/side-panel projection and gates mutations via a modal. Imports NO LLM/provider SDK.",
  "type": "module",
  "private": true,
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    }
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "bin": {
    "production-master": "./dist/cli.js"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsc -b tsconfig.json",
    "typecheck": "tsc -b tsconfig.json --noEmit",
    "test": "vitest run"
  },
  "dependencies": {
    "@production-master/plugin-core": "0.1.1"
  },
  "license": "MIT"
}

